function navItem(v,label){return `<button class="nav-btn ${view===v||(view==='editor'&&v===(editRole==='opponent'?'battle':'decks'))||(v==='analysis'&&view==='replay')||(v==='battle'&&view==='manual')?'active':''}" data-action="nav" data-view="${v}">${icon(v)}<span>${label}</span></button>`;}
function shell(html){root.innerHTML=`<header class="app-header"><button class="brand" data-action="nav" data-view="decks"><img src="assets/icon.svg" alt="" class="brand-symbol"><span><strong>デッキラボ</strong><small>DUEL MASTERS · DECK LAB</small></span></button><div class="header-meta"><span><i class="dot-live"></i>この端末に保存</span><span class="mobile-hide">紙のデュエマ / オリジナル</span><button class="icon-btn" data-action="about" aria-label="対応範囲とルール" style="color:#c4d2db">${icon('help')}</button></div></header><div class="app-shell"><aside class="sidebar">${navItem('decks','マイデッキ')}${navItem('draw','初手・ドロー')}${navItem('battle','対戦する')}${navItem('analysis','分析・比較')}${navItem('history','対戦履歴')}<div class="sidebar-foot"><span class="version-pill">EARLY ACCESS · v0.18</span><p>組む。試す。もっと強く。</p><p>登録 ${fmt(cards.length)}種類 / 同名で集約<br>対戦対応 ${battleCards.length}種類</p><button class="details-link" data-action="about">対応範囲・データについて ${icon('chevron',11)}</button></div></aside><main class="main ${view==='battle'?'match-page':''}" id="main">${!storageOK?'<div class="data-warning">保存できませんでした。デッキを書き出して保管してください。</div>':''}${html}</main></div><nav class="bottom-nav" aria-label="メインメニュー">${navItem('decks','デッキ')}${navItem('draw','初手')}${navItem('battle','対戦')}${navItem('analysis','分析')}${navItem('history','履歴')}</nav>`;}
function pageHead(title,sub,actions='',eyebrow='DECK LAB'){return `<div class="page-head"><div class="page-title"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>`;}
function art(id,{mini=false}={}){const c=card(id);if(!c)return '';if(!c.supported)return `<span class="art-card name-card ${c.faces?.length?'with-data':''}">${c.faces?.length?`<span class="data-cost">${esc(costLabel(c))}</span><span class="data-civs">${cardCivilizations(c).map(v=>`<i style="background:${color[v]}" title="${esc(v)}"></i>`).join('')}</span>`:''}<span class="name-card-mark">${icon('decks',30)}</span><span class="name-card-title">${esc(c.name)}</span><span class="name-card-foot">${c.faces?.length?'CARD DATA':'CARD NAME'}</span></span>`;return `<span class="art-card" style="--civ-color:${color[cardCivilizations(c)[0]]};--art-pos:${pos[cardCivilizations(c)[0]]}%"><span class="art"></span><span class="cost">${c.cost}</span>${c.trigger?'<span class="trigger-mark">S・T</span>':''}<span class="card-bottom">${esc(c.name)}<span class="power">${c.power?fmt(c.power):'SPELL'}</span></span></span>`;}
function miniDeck(d){const ids=[...d.cards].filter(r=>card(r.id)).sort((a,b)=>(card(a.id).type==='creature'?0:1)-(card(b.id).type==='creature'?0:1)).slice(0,3);return `<span class="mini-deck">${ids.map(r=>art(r.id,{mini:true})).join('')}</span>`;}
function dots(d){const colors=[...new Set(d.cards.flatMap(r=>cardCivilizations(card(r.id))))];return `<span class="color-dots">${colors.map(c=>`<span class="civ-dot" style="background:${color[c]}" title="${c}"></span>`).join('')}</span>`;}
