function deckCard(d){return `<article class="deck-card ${saved.selected===d.id?'selected':''}"><div class="deck-banner"><div class="art-bg ${card(d.cards[0]?.id)?.supported?'':'neutral'}" style="background-position:${pos[card(d.cards[0]?.id)?.civ]||0}% 30%"></div><div class="deck-banner-top"><span class="badge">オリジナル</span><span class="badge ${saved.selected===d.id?'green':''}">${saved.selected===d.id?'使用中':'端末に保存'}</span></div><div class="deck-banner-bottom">MY DECK / ${fmt(sum(d))} CARDS</div></div><div class="deck-body"><div class="row spread"><h2>${esc(d.name)}</h2><button class="icon-btn" data-action="deck-menu" data-id="${esc(d.id)}" aria-label="デッキの操作">${icon('settings',18)}</button></div><div class="deck-meta">${dots(d)}<span>${sum(d)}枚</span><span>·</span><span>${d.cards.length}種類</span><span>·</span><span>${registrationErrors(d).length?'編集中':coverage(d).unsupported?'初手確認できます':'対戦可能'}</span></div><div class="deck-actions"><button class="btn primary" data-action="draw-deck" data-id="${esc(d.id)}">${icon('draw',15)}初手を試す</button><button class="btn" data-action="use-deck" data-id="${esc(d.id)}">対戦</button><button class="btn" data-action="edit" data-id="${esc(d.id)}">${icon('edit',14)}編集</button></div></div></article>`;}
function renderDecks(){const total=saved.history.reduce((s,r)=>s+r.stats.total,0);shell(`${pageHead('マイデッキ','自分だけの構成をつくって、対戦で確かめよう。','','YOUR COLLECTION')}<div class="home-stats"><div class="stat-tile"><span class="stat-icon">${icon('decks',20)}</span><div><small>保存したデッキ</small><strong>${saved.decks.length}<small>デッキ</small></strong></div></div><div class="stat-tile"><span class="stat-icon">${icon('battle',20)}</span><div><small>シミュレーション</small><strong>${fmt(total)}<small>戦</small></strong></div></div><div class="stat-tile"><span class="stat-icon">${icon('history',20)}</span><div><small>分析レポート</small><strong>${saved.history.length}<small>件</small></strong></div></div></div><div class="row spread mb16"><h2>デッキ一覧 <span class="count-chip">${saved.decks.length}</span></h2><button class="details-link" data-action="import-text">${icon('upload',13)} リストを読み込む</button></div><div class="deck-grid">${saved.decks.map(deckCard).join('')}<button class="empty-card" data-action="new-deck"><span class="round-icon">${icon('plus',25)}</span><h3>新しいデッキを作る</h3><p>カード一覧・写真・スクリーンショットから登録</p></button></div><div class="mt24">${notice(`<strong>最初の1戦は、ここから。</strong><br>マイデッキ01は練習用の構成です。編集して自分のデッキに変えたり、そのまま対戦を試せます。<br>同名でまとめた${fmt(cards.length)}種類を登録できます。名前・文明・コスト・種類・能力文を確認・検索できます。初手・ドローは全登録カードで確認可能。効果を処理する対戦は${battleCards.length}種類に対応しています。`)}</div><p class="art-disclaimer">カードのイラストは識別補助用のオリジナル画像です。実際のカード画像ではありません。</p>`);}
function curve(d){const values=Array(9).fill(0);for(const r of d.cards){const c=card(r.id);const cost=primaryCost(c);if(cost!==null)values[Math.min(cost,8)]+=r.count;}const max=Math.max(...values,1);return `<div class="curve">${values.map((n,i)=>`<div class="curve-col"><div class="curve-bar" style="height:${n/max*53}px"><span>${n||''}</span></div><small>${i===8?'8+':i}</small></div>`).join('')}</div>`;}
function startEdit(d,{target='mine',tab='cards'}={}){editRole=target;edit=clone(d||{id:uid(),name:target==='opponent'?'新しい相手デッキ':'新しいデッキ',cards:[],format:'original',category:target==='opponent'?'相手':'自分',created:new Date().toISOString()});if(target==='opponent'){comparisonId=null;allOpp=false;}query='';civ='';costFilter='';typeFilter='';page=0;editTab=tab;photo=null;view='editor';render();window.scrollTo(0,0);}
function tournamentHTML(d){const t=d.tournament;if(!t)return '';return `<div class="tournament-note"><strong>作成元：${esc(t.event)}</strong><p>${esc(t.player)} · ${esc(t.result)} · 大会当時の構成</p><a class="details-link" href="${esc(t.source)}" target="_blank" rel="noopener">公式の大会リストを確認 ↗</a><small>リスト確認：${esc(t.checkedAt)}。現在の大会での使用可否は、最新の使用制限を確認してください。</small></div>`;}
function environmentProgressHTML(d,{target=false}={}){
 const p=environmentSupport(d,registry),complete=p.supportedCopies===p.totalCopies;
 return `<section class="environment-support ${target?'target-support':''}" aria-label="${esc(d.name)}の効果対応状況">${target?'<span class="badge green">優先して対応中</span><h3 class="mt8">'+esc(d.name)+'</h3>':''}<div class="row spread mt8"><strong>効果対応 ${p.supportedCopies} / ${p.totalCopies}枚</strong><small>${p.supportedTypes} / ${p.totalTypes}種類</small></div><progress max="${p.totalCopies}" value="${p.supportedCopies}" aria-label="${esc(d.name)}の対応枚数"></progress>${target?`<p class="small">${complete?'全カードの効果実装済み。デッキ単位の検証を進めます。':'現在はカード効果を実装中です。この大会リストでの対戦は、残りの効果対応後に検証します。'}</p><ol class="support-roadmap"><li class="current">1. カード効果</li><li>2. デッキ対戦の検証</li><li>3. AI・分析の改善</li></ol>`:''}<details class="mt8"><summary>カードごとの対応を見る</summary><div class="environment-support-list mt8">${d.cards.map(r=>{const c=card(r.id);return `<div><button class="details-link" data-action="card-detail" data-id="${esc(c.id)}">${esc(c.name)}</button><span class="${c.supported?'green':'muted'}">${r.count}枚 · ${c.supported?'効果対応済み':'未対応'}</span></div>`;}).join('')}</div></details></section>`;
}
function environmentHTML(){const opponent=editRole==='opponent',target=environmentDecks.find(d=>d.id===ENVIRONMENT_TARGET);return `<div class="environment-intro"><span class="badge green">公式大会リスト ${environmentDecks.length}件</span><h2>${opponent?'大会リストを相手に選ぶ':'選ぶだけで、40枚を自動作成。'}</h2><p>${opponent?'選んだ40枚を相手デッキとして保存します。登録後にカード一覧から編集できます。':'DMGP2026-1stの入賞リストを収録。カードを1枚ずつ選ばずに保存して、そのまま編集・初手確認ができます。'}</p><small>大会当時のリストです。最新環境のランキングや自動更新ではありません。確認：2026-10-20</small></div>${target?environmentProgressHTML(target,{target:true}):''}<div class="mb16">${notice('収録デッキは効果未対応カードを含むため、現在は初手・ドローの検証用です。効果込みの手動・自動対戦はまだ利用できません。','amber')}</div><div class="environment-grid">${environmentDecks.map(d=>`<article class="panel environment-card"><div class="row spread"><span class="badge green">${esc(d.tournament.result)}</span><span class="badge">オリジナル · ${sum(d)}枚</span></div><div class="environment-preview">${miniDeck(d)}<div class="grow"><h2>${esc(d.name)}</h2><div class="row gap8 mt8">${dots(d)}<small>${d.cards.length}種類</small></div></div></div><p class="small">${esc(d.tournament.event)}</p><p class="source-note mt8">${esc(d.tournament.player)} · 効果未対応 ${coverage(d).unsupported}枚</p>${environmentProgressHTML(d)}<div class="mt8">${readinessHTML(d)}</div><div class="environment-card-actions"><button class="btn" data-action="deck-detail" data-id="${esc(d.id)}">40枚を見る</button><button class="btn primary" data-action="create-environment" data-id="${esc(d.id)}">${icon('bolt',14)}${opponent?'相手に選ぶ':'この40枚で作成'}</button></div><a class="details-link mt16" href="${esc(d.tournament.source)}" target="_blank" rel="noopener">公式リスト ↗</a></article>`).join('')}</div><p class="source-note mt24">作成したデッキはこの端末に保存されます。同じ40枚の${opponent?'相手デッキ':'マイデッキ'}がある場合は、そのデッキを選択します。</p>`;}

